    case TextEndEvent(:final contentIndex):
    case ThinkingEndEvent(:final contentIndex):
    case ToolCallEndEvent(:final contentIndex):
      if (contentIndex > run.lastEnded) run.lastEnded = contentIndex;
      run.forward(event);
