      addTearDown(lab.shutdown);
      final o1 = await streamedCall(lab.url);
      expect(o1.kind, 'ok');
      final p1 = lab.ports.single;
      await Future<void>.delayed(const Duration(milliseconds: 300));
      final o2 = await streamedCall(lab.url);
