          'text/event-stream',
        );
        request.response.add(utf8.encode('data: {"delta":"first"}\n\n'));
        await request.response.flush();
        await holdOpen.future; // alive but silent from here on
      });
      return Uri.parse('http://127.0.0.1:${server.port}/v1/chat');
