/// live token again. A user cancel never reaches this —
/// `_replaysAttempt` stands it before the outcome exists.
void _rearmWatchdogLatch(CancelToken? cancelToken, bool watchdogReplay) {
  if (watchdogReplay) {
    cancelToken?.reset();
