    );
    final wrapper = resolver.streamForRole('default');
    final events = await wrapper
        .call(wrapper.currentModel, const Context(messages: []))
        .toList();
    expect(slept, isEmpty);
    expect(events.last, isA<DoneEvent>());
  });
}

