          .where((f) => f.path.endsWith('meta.json'));
      expect(dumps, isNotEmpty, reason: 'the dump exists once the abort lands');
      final meta =
          jsonDecode(dumps.first.readAsStringSync()) as Map<String, dynamic>;
      expect(meta['watchdog'], 'stream-idle');
