  // from https://www.rfc-editor.org/rfc/rfc2616#page-15
  //
  // CTL            = <any US-ASCII control character
  //                  (octets 0 - 31) and DEL (127)>
  // separators     = "(" | ")" | "<" | ">" | "@"
  //                | "," | ";" | ":" | "\" | <">
  //                | "/" | "[" | "]" | "?" | "="
  //                | "{" | "}" | SP | HT
