  const _validChars =
      r"                                "
      r" ! #$%&'  *+ -. 0123456789      "
      r" ABCDEFGHIJKLMNOPQRSTUVWXYZ   ^_"
      r"`abcdefghijklmnopqrstuvwxyz | ~ ";
  for (int codeUnit in token.codeUnits) {
